---@param event string event name
---@param multiple boolean is multiple value
---@param eventMap table|nil extra event key value
function ReportEvent.reportEvent(key, event, multiple, eventMap)
    local data = ReportValueDataMap[tostring(key)]
    if not data then
        LogUtil.logError("report value data is nil, key=" .. tostring(key))
        return
    end
    local valueKeyMap = EventConfig:getEventValueKey(event)
    if not valueKeyMap then
        LogUtil.logError("report event is not find, event=" .. event)
        return
    end
    local userId = tonumber(key)
    if not userId then
        local players = PlayerManager:getPlayers()
        if not TableUtil.isEmpty(players) then
            userId = players[1].userId
        end
    end
    if not userId then
        LogUtil.logError("report event key = nil, event=" .. event)
        return
    end
    eventMap = eventMap or {}
    for valueKey, valueType in pairs(valueKeyMap) do
        local value = data:getValue(valueKey)
        if type(value) == "function" then
            eventMap[valueKey] = value()
        elseif value ~= nil then
            eventMap[valueKey] = value
        elseif eventMap[valueKey] == nil then
            if valueType == "number" then
                eventMap[valueKey] = 0
            elseif valueType == "string" then
                eventMap[valueKey] = ""
            end
        end
    end
    if multiple then
        local multipleValue = data:getMultipleValues(event)
        if multipleValue then
            for _, item in pairs(multipleValue) do
                local newEventMap = TableUtil.copyTable(eventMap)
                for valueKey, value in pairs(item.__condition) do
                    if valueKeyMap[valueKey] ~= nil then
                        newEventMap[valueKey] = value
                    end
                end
                for valueKey, value in pairs(item) do
                    if valueKeyMap[valueKey] ~= nil then
                        newEventMap[valueKey] = value
                    end
                end
                if isClient then
                    GameAnalytics:newDesign(event, newEventMap)
                else
                    GameAnalytics:newDesign(userId, event, newEventMap)
                end
            end
        end
    else
        if isClient then
            return GameAnalytics:newDesign(event, eventMap)
        else
            return GameAnalytics:newDesign(userId, event, eventMap)
        end
    end
